{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const URL_LOGIN = 'https://app.cotadorsimplificado.com.br/login';

  try {
    await page.setViewport({ width: 1280, height: 800 });
    await page.goto(URL_LOGIN, { waitUntil: 'networkidle2', timeout: 60000 });
    await new Promise(r => setTimeout(r, 3000));

    // ETAPA 1: Preencher email e clicar em Continuar
    const emailInput = await page.$('#email_principal');
    if (emailInput) {
      await emailInput.click();
      await emailInput.type(EMAIL, { delay: 30 });
    }

    await new Promise(r => setTimeout(r, 1000));

    // Clicar no botao 'Continuar com Email'
    let buttons = await page.$$('button');
    for (const btn of buttons) {
      const text = await page.evaluate(el => el.textContent, btn);
      if (text && text.includes('Continuar com Email')) {
        await btn.click();
        break;
      }
    }

    // Aguardar campo de senha aparecer
    await new Promise(r => setTimeout(r, 3000));
    await page.waitForSelector('#pwdInput', { timeout: 15000 });

    // ETAPA 2: Preencher senha
    const senhaInput = await page.$('#pwdInput');
    if (senhaInput) {
      await senhaInput.click();
      await senhaInput.type(SENHA, { delay: 30 });
    }

    await new Promise(r => setTimeout(r, 1000));

    // Clicar especificamente no botao 'Entrar'
    buttons = await page.$$('button');
    for (const btn of buttons) {
      const text = await page.evaluate(el => el.textContent.trim(), btn);
      if (text === 'Entrar') {
        await btn.click();
        break;
      }
    }

    // Aguardar navegacao apos login
    await new Promise(r => setTimeout(r, 8000));

    // Listar todos os elementos clicaveis
    const clickables = await page.$$eval('a, button, [onclick], [role="button"]', els => els.map(el => ({
      tag: el.tagName,
      text: el.textContent.trim().substring(0, 100),
      href: el.href || null,
      className: el.className
    })));

    // Procurar por texto que contenha 'hapvida' ou 'cotar'
    const relevantes = clickables.filter(el => 
      el.text.toLowerCase().includes('hapvida') || 
      el.text.toLowerCase().includes('cotar') ||
      el.text.toLowerCase().includes('cotador')
    );

    return {
      url: page.url(),
      title: await page.title(),
      totalElementos: clickables.length,
      elementosRelevantes: relevantes,
      primeiros20: clickables.slice(0, 20)
    };
  } catch (error) {
    return {
      success: false,
      error: error.message
    };
  }
}"
}
